  `reservaID` int NOT NULL AUTO_INCREMENT,
  `clienteID` int DEFAULT NULL,
  `habitacionID` int NOT NULL,
  `formaPagoID` int DEFAULT NULL,
  `fecha_reserva` datetime DEFAULT CURRENT_TIMESTAMP,
  `checkin` datetime NOT NULL,
  `monto_reserva` float NOT NULL,
  `monto_pagado` float DEFAULT '0',
  `monto_pendiente` float DEFAULT NULL,
  `estado` enum('PENDIENTE','CONFIRMADA','CANCELADA') DEFAULT 'PENDIENTE',
  `estado2` enum('ACTIVO','INACTIVO') DEFAULT 'ACTIVO',
  PRIMARY KEY (`reservaID`),
  KEY `clienteID` (`clienteID`),
  KEY `formaPagoID` (`formaPagoID`),
  KEY `habitacionID` (`habitacionID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

--
-- Disparadores `reservas`
--
DROP TRIGGER IF EXISTS `actualizar_estado_habitacion_reservada`;
DELIMITER $$
CREATE TRIGGER `actualizar_estado_habitacion_reservada` AFTER INSERT ON `reservas` FOR EACH ROW BEGIN
    -- Actualiza el estado de la habitación a 'RESERVADA' cuando se inserta una nueva reserva
    UPDATE habitaciones
    SET estado = 'RESERVADA'
    WHERE habitacionID = NEW.habitacionID;
END
$$
DELIMITER ;
DROP TRIGGER IF EXISTS `registrar_ingreso_reserva`;
DELIMITER $$
CREATE TRIGGER `registrar_ingreso_reserva` AFTER INSERT ON `reservas` FOR EACH ROW BEGIN 
    IF (NEW.monto_pagado > 0) THEN 
        -- Insertar el ingreso usando el monto_pagado de la tabla reservas 
        VALUES (NOW(), NOW(), NEW._usuario, 'A', NEW.monto_pagado, NEW.formaPagoID, NEW.reservaID); 
    END IF; 
END
$$
DELIMITER ;

