DELIMITER $$
--
-- Eventos
--
DROP EVENT IF EXISTS `revisar_habitaciones_novencidas`$$
CREATE DEFINER=`root`@`localhost` EVENT `revisar_habitaciones_novencidas` ON SCHEDULE EVERY 1 MINUTE STARTS '2025-05-07 21:47:28' ON COMPLETION NOT PRESERVE ENABLE DO UPDATE habitaciones h
    JOIN hospedajes hos ON h.habitacionID = hos.habitacionID
    SET h.estado = 'OCUPADA'
    WHERE TIMESTAMPDIFF(SECOND, hos.checkout, NOW()) < 0 -- Verifica que la hora actual sea mayor al checkout
    AND hos.estado = 'ACTIVO'  -- Solo cambiar si el hospedaje está ACTIVO
    AND h.estado = 'DEUDA';$$

DROP EVENT IF EXISTS `revisar_habitaciones_vencidas`$$
CREATE DEFINER=`root`@`localhost` EVENT `revisar_habitaciones_vencidas` ON SCHEDULE EVERY 1 MINUTE STARTS '2025-05-07 21:47:22' ON COMPLETION NOT PRESERVE ENABLE DO UPDATE habitaciones h
    JOIN hospedajes hos ON h.habitacionID = hos.habitacionID
    SET h.estado = 'DEUDA'
    WHERE TIMESTAMPDIFF(SECOND, hos.checkout, NOW()) > 0 -- Verifica que la hora actual sea mayor al checkout
    AND hos.estado = 'ACTIVO'  -- Solo cambiar si el hospedaje está ACTIVO
    AND h.estado = 'OCUPADA';$$

DELIMITER ;
